private final void parseSingleDelimiterRecord() {
    boolean inQuotes = false;
    boolean valueStarted = false;
    output.trim = ignoreTrailingWhitespace;

    if (ch <= ' ' && ignoreLeadingWhitespace && whitespaceRangeStart < ch) {
        ch = input.skipWhitespace(ch, delimiter, quote);
    }

    while (true) {
        if (ch == newLine) {
            if (!inQuotes) break;
        }

        if (ch == delimiter && !inQuotes) {
            output.valueParsed();
            valueStarted = false;
            try {
                ch = input.nextChar();
                if (ch == newLine) {
                    break;
                }
                continue;
            } catch (EOFException e) {
                return;
            }
        }

        if (ch == quote) {
            if (!valueStarted) {
                inQuotes = true;
                valueStarted = true;
                ch = input.nextChar();
                continue;
            } else {
                if (inQuotes) {
                    char nextChar;
                    try {
                        nextChar = input.nextChar();
                    } catch (EOFException e) {
                        output.valueParsed();
                        return;
                    }
                    if (nextChar == quote) {
                        output.appender.append(ch);
                        ch = input.nextChar();
                    } else {
                        inQuotes = false;
                        ch = nextChar;
                        if (ch == delimiter) {
                            output.valueParsed();
                            valueStarted = false;
                            ch = input.nextChar();
                            if (ch == newLine) {
                                break;
                            }
                            continue;
                        } else if (ch == newLine) {
                            output.valueParsed();
                            break;
                        }
                    }
                } else {
                    output.appender.append(ch);
                }
            }
        } else {
            valueStarted = true;
            output.appender.append(ch);
        }

        try {
            ch = input.nextChar();
        } catch (EOFException e) {
            if (valueStarted) {
                output.valueParsed();
            }
            return;
        }
    }

    if (valueStarted || ch == delimiter) {
        output.valueParsed();
    }

    try {
        if (ch != newLine) {
            ch = input.nextChar();
        }
    } catch (EOFException e) {
        return;
    }
}
